"""Imported serverless credentials must authenticate in the local Python runtime."""
import os
import unittest
os.environ.setdefault('SECRET_KEY', 'password-import-test-secret')
os.environ.setdefault('DATABASE_URL', 'postgresql+asyncpg://test:test@localhost/test')
from security import verify_password, hash_password

# Generated by serverless/src/crypto.ts hashPassword, including UTF-8 input.
VECTOR = 'pbkdf2_sha256$210000$efQSdVLVMvIxidzzHSLpXA$4mwDckrnGHdzvix9cXdz7N5TBJ-N1JcfDceuLVPGCyE'

class PasswordImportTests(unittest.TestCase):
    def test_serverless_password_verifies_and_wrong_password_fails(self):
        self.assertTrue(verify_password('imported-password-✓', VECTOR))
        self.assertFalse(verify_password('wrong-password', VECTOR))

    def test_existing_local_credential_still_authenticates(self):
        stored = hash_password('local-password')
        self.assertTrue(verify_password('local-password', stored))
        self.assertFalse(verify_password('wrong-password', stored))

    def test_invalid_imported_hashes_fail_without_unbounded_work(self):
        for stored in ['', 'invalid', VECTOR + '$extra', VECTOR.replace('210000', '999999999999'),
                       VECTOR.replace('210000', '0'), 'pbkdf2_sha256$210000$!$!']:
            with self.subTest(stored=stored):
                self.assertFalse(verify_password('imported-password-✓', stored))
